#!/usr/bin/env bash
set -Eeuo pipefail

VERSION="2.5.2"
APP_VERSION="NOVA-2.5.2"
REV="ROOT-MEMORY-LIVENESS-R6"
ZIP_NAME="QUANT_NOVA_2.5.2_ROOT_MEMORY_LIVENESS_R6.zip"
ROOT_NAME="nova2520"
EXPECTED_ZIP_SHA256="b7ff96be59a9c1a1ee0b3e675ca82b8beefe9335f5a0d8f2d0d62c4b1c0b2f32"
APP_DIR="$HOME/quant-nova"
CONTAINER="quant-nova"
NETWORK="kiwoom-net"
HOST_PORT="${NOVA_HOST_PORT:-3200}"
ACTIVE_MEM="${NOVA_ACTIVE_MEMORY_LIMIT:-520m}"
CANDIDATE_MEM="${NOVA_CANDIDATE_MEMORY_LIMIT:-320m}"
STAMP="$(date +%Y%m%d%H%M%S)"
IMAGE="quant-nova:2.5.2-root-r6-${EXPECTED_ZIP_SHA256:0:12}"
BACKUP="quant-nova-backup-root252-r6-$STAMP"
FAILED="quant-nova-failed-root252-r6-$STAMP"
STAGE="quant-nova-stage-root252-r6-$STAMP"
CANDIDATE="quant-nova-candidate-root252-r6-$STAMP"
TMP="$(mktemp -d)"
DEPLOY_DIR="$APP_DIR/deployments/root252-r6-$STAMP"
GUARD_STATIC="$APP_DIR/http-guard-v2/static"
GUARD_CACHE="$APP_DIR/http-guard-v2/cache"
GUARD_BK="$DEPLOY_DIR/http-guard-static-before"
RUNTIME_ENV="$TMP/runtime.env"
CUTOVER=0
SUCCESS=0
OLD_RENAMED=0
GUARD_SYNCED=0

say(){ printf '\n==> %s\n' "$*"; }
fail(){ echo "ERROR: $*" >&2; exit 1; }

on_exit(){
  ec=$?
  trap - EXIT
  sudo docker rm -f "$CANDIDATE" >/dev/null 2>&1 || true
  sudo docker rm -f "$STAGE" >/dev/null 2>&1 || true
  if [[ $SUCCESS -ne 1 && $CUTOVER -eq 1 ]]; then
    echo "[자동복구] 2.5.2 cutover 실패 — immutable 이전 컨테이너 복구" >&2
    if sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
      sudo docker stop -t 5 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
      sudo docker rename "$CONTAINER" "$FAILED" >/dev/null 2>&1 || true
    fi
    if [[ $OLD_RENAMED -eq 1 ]] && sudo docker inspect "$BACKUP" >/dev/null 2>&1; then
      sudo docker rename "$BACKUP" "$CONTAINER" >/dev/null 2>&1 || true
      sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
    fi
    if [[ $GUARD_SYNCED -eq 1 && -d "$GUARD_BK" && -d "$GUARD_STATIC" ]]; then
      sudo rm -rf "$GUARD_STATIC"/* >/dev/null 2>&1 || true
      sudo cp -a "$GUARD_BK"/. "$GUARD_STATIC"/ >/dev/null 2>&1 || true
      sudo rm -f "$GUARD_CACHE"/* >/dev/null 2>&1 || true
    fi
  fi
  rm -rf "$TMP" >/dev/null 2>&1 || true
  if [[ $SUCCESS -eq 1 ]]; then exit 0; else exit "${ec:-1}"; fi
}
trap on_exit EXIT

[[ "$(id -u)" -ne 0 ]] || fail "root shell이 아니라 ubuntu 사용자 + sudo로 실행하세요."
for c in python3 curl sha256sum base64 awk df free; do command -v "$c" >/dev/null 2>&1 || fail "필수 명령 없음: $c"; done
sudo docker info >/dev/null 2>&1 || fail "Docker daemon 접근 실패"
[[ -s "$APP_DIR/.env" ]] || fail "$APP_DIR/.env 없음 또는 빈 파일"
[[ -d "$APP_DIR/data" ]] || fail "$APP_DIR/data 없음"
sudo docker inspect "$CONTAINER" >/dev/null 2>&1 || fail "현재 quant-nova 컨테이너 없음 — rollback 원본이 없어 중단"
FREE_KB="$(df -Pk "$HOME" | awk 'NR==2{print $4}')"
[[ ${FREE_KB:-0} -ge 524288 ]] || fail "디스크 여유 512MB 미만"
mkdir -p "$DEPLOY_DIR"

say "1/9 Root-cause preflight — active는 수정하지 않음"
echo "POLICY=IMMUTABLE_ROOT_MEMORY_FIX"
echo "ACTIVE_UNTOUCHED_UNTIL_PRODUCTION_DATA_CANDIDATE_PASS=YES"
echo "BUY_SIGNAL_LOGIC_CHANGED=NO"
echo "RAW_TICK_SCORING_HORIZON=300s RETENTION=330s"
echo "ACTIVE_MEMORY_LIMIT=$ACTIVE_MEM no-container-swap"
echo "CANDIDATE_MEMORY_LIMIT=$CANDIDATE_MEM no-container-swap"
free -m
BASE_IMAGE_ID="$(sudo docker inspect "$CONTAINER" --format '{{.Image}}')"
[[ -n "$BASE_IMAGE_ID" ]] || fail "기존 image id 확인 실패"
sudo docker inspect "$BASE_IMAGE_ID" >/dev/null 2>&1 || fail "기존 image가 로컬에 없음"
sudo docker inspect "$CONTAINER" --format '{{range .Config.Env}}{{println .}}{{end}}' > "$RUNTIME_ENV"
chmod 600 "$RUNTIME_ENV"

say "2/9 Embedded CLEAN package 복원 + SHA 검증"
base64 -d > "$TMP/$ZIP_NAME" <<'NOVA252_R6_PAYLOAD'
