NOVA252_R6_PAYLOAD
ACTUAL="$(sha256sum "$TMP/$ZIP_NAME" | awk '{print $1}')"
[[ "$ACTUAL" == "$EXPECTED_ZIP_SHA256" ]] || fail "ZIP SHA256 불일치 expected=$EXPECTED_ZIP_SHA256 actual=$ACTUAL"
python3 - "$TMP/$ZIP_NAME" "$TMP" <<'PYEX'
import sys,zipfile
z=zipfile.ZipFile(sys.argv[1]);bad=z.testzip();assert bad is None,bad;z.extractall(sys.argv[2]);print('ZIP_TEST=PASS')
PYEX
ROOT="$TMP/$ROOT_NAME"
python3 "$ROOT/scripts/build_context_check.py" --mode package
(cd "$ROOT" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null)
python3 - "$ROOT/BUILD_INFO.json" <<'PYBI'
import json,sys
b=json.load(open(sys.argv[1]))
assert b.get('version')=='NOVA-2.5.2',b
assert b.get('policy')=='ROOT_MEMORY_LIVENESS_R6',b
assert b.get('installer_rev')=='2.5.2-ROOT-MEMORY-LIVENESS-R6',b
print('BUILD_INFO=PASS')
PYBI

say "3/9 Offline gates — syntax/selfcheck/active-memory regression"
python3 -m py_compile "$ROOT/app/main.py" "$ROOT/app/realtime_core.py" "$ROOT/app/runtime_health.py" "$ROOT/scripts/selfcheck.py" "$ROOT/scripts/active_runtime_loadtest.py" "$ROOT/scripts/build_context_check.py"
python3 "$ROOT/scripts/selfcheck.py"

grep -Fq "APP_VERSION='NOVA-2.5.2'" "$ROOT/app/main.py"
grep -Fq "KEEP_RAW_TICKS_330S_ONLY_NO_SIGNAL_STATE_DELETION" "$ROOT/app/main.py"
grep -Fq "async def memory_guard_loop" "$ROOT/app/main.py"
grep -Fq "_tail_text_lines" "$ROOT/app/main.py"
echo "ROOT_FIX_STATIC_GATE=PASS"

say "4/9 Immutable image 생성 — 기존 active filesystem은 건드리지 않음"
sudo docker rm -f "$STAGE" >/dev/null 2>&1 || true
sudo docker create --name "$STAGE" --network none --user 0:0 --entrypoint /bin/sh "$BASE_IMAGE_ID" -c 'sleep 3600' >/dev/null
sudo docker start "$STAGE" >/dev/null
sudo docker exec "$STAGE" /bin/sh -lc 'find /app -mindepth 1 -maxdepth 1 ! -name data -exec rm -rf -- {} +; mkdir -p /app'
for x in app static config scripts; do sudo docker cp "$ROOT/$x" "$STAGE:/app/$x"; done
for x in BUILD_INFO.json SOURCE_MANIFEST.sha256 ARCHITECTURE_CLEAN_2.5.0.md DEPLOYMENT_GATES.md README_KO.md REBUILD_AUDIT_20260812.txt ROOT_CAUSE_FIX_2.5.2.md requirements.txt; do sudo docker cp "$ROOT/$x" "$STAGE:/app/$x"; done
sudo docker exec "$STAGE" python /app/scripts/build_context_check.py --mode runtime
sudo docker exec "$STAGE" python -c 'import fastapi,uvicorn,httpx,websockets,pywebpush,cryptography;print("RUNTIME_DEPS=PASS")'
sudo docker exec -e NOVA_DATA_DIR=/tmp/nova-selfcheck "$STAGE" python /app/scripts/selfcheck.py >/dev/null
sudo docker exec -e NOVA_DATA_DIR=/tmp/nova-active-gate "$STAGE" python /app/scripts/active_runtime_loadtest.py
sudo docker exec "$STAGE" /bin/sh -lc 'find /app -type d -name __pycache__ -prune -exec rm -rf {} +; find /app -type f -name "*.pyc" -delete' >/dev/null 2>&1 || true
sudo docker commit \
  --change 'ENV PYTHONDONTWRITEBYTECODE=1 PYTHONUNBUFFERED=1 PORT=8000 NOVA_DATA_DIR=/app/data' \
  --change 'WORKDIR /app' \
  --change 'ENTRYPOINT []' \
  --change 'CMD ["python","-m","uvicorn","app.main:app","--host","0.0.0.0","--port","8000"]' \
  "$STAGE" "$IMAGE" >/dev/null
sudo docker rm -f "$STAGE" >/dev/null
sudo docker image inspect "$IMAGE" >/dev/null

say "5/9 Production-data shadow — 실제 data 복사본 + memory/no-swap gate"
CAND_PORT="$(python3 - <<'PYPORT'
import socket
s=socket.socket();s.bind(('127.0.0.1',0));print(s.getsockname()[1]);s.close()
PYPORT
)"
mkdir -p "$TMP/candidate-data"
cp -a "$APP_DIR/data"/. "$TMP/candidate-data"/
chmod -R u+rwX "$TMP/candidate-data"
sudo docker run -d --name "$CANDIDATE" --network "$NETWORK" --env-file "$RUNTIME_ENV" \
  --memory "$CANDIDATE_MEM" --memory-swap "$CANDIDATE_MEM" --pids-limit 256 \
  -e PORT=8000 -e NOVA_DATA_DIR=/app/data -e NOVA_CANDIDATE_MODE=1 \
  -v "$TMP/candidate-data:/app/data" -p "127.0.0.1:${CAND_PORT}:8000" \
  --entrypoint /bin/sh "$IMAGE" -c 'exec python -m uvicorn app.main:app --host 0.0.0.0 --port "${PORT:-8000}"' >/dev/null
CAND_OK=0
for i in $(seq 1 80); do
  J="$(curl -fsS --connect-timeout 1 --max-time 2 "http://127.0.0.1:${CAND_PORT}/api/livez" 2>/dev/null || true)"
  if [[ -n "$J" ]] && printf '%s' "$J" | python3 -c 'import sys,json;j=json.load(sys.stdin);raise SystemExit(0 if j.get("ok") and j.get("version")=="NOVA-2.5.2" and j.get("candidate_mode") is True else 1)' 2>/dev/null; then CAND_OK=1;break;fi
  sleep .25
done
[[ $CAND_OK -eq 1 ]] || { sudo docker logs --tail 250 "$CANDIDATE" || true; fail "production-data candidate livez 실패"; }
for i in $(seq 1 20); do curl -fsS -o /dev/null --connect-timeout 1 --max-time 1.5 "http://127.0.0.1:${CAND_PORT}/api/livez" || fail "candidate soak fail $i"; sleep .25; done
CAND_SWAP_KB="$(sudo docker exec "$CANDIDATE" sh -c "awk '/VmSwap:/{print \$2}' /proc/1/status" 2>/dev/null || echo 0)"
[[ "${CAND_SWAP_KB:-0}" -eq 0 ]] || fail "candidate가 swap 사용: ${CAND_SWAP_KB}KB"
CAND_MEM="$(sudo docker stats --no-stream --format '{{.MemUsage}}' "$CANDIDATE")"
echo "PRODUCTION_DATA_CANDIDATE=PASS memory=$CAND_MEM swap_kb=${CAND_SWAP_KB:-0}"
sudo docker rm -f "$CANDIDATE" >/dev/null

say "6/9 Atomic cutover — 지금 처음 active 교체"
if [[ -d "$GUARD_STATIC" ]]; then mkdir -p "$GUARD_BK"; sudo cp -a "$GUARD_STATIC"/. "$GUARD_BK"/ >/dev/null 2>&1 || true; fi
CUTOVER=1
sudo docker stop -t 15 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
sudo docker rename "$CONTAINER" "$BACKUP"; OLD_RENAMED=1
sudo docker run -d --name "$CONTAINER" --restart unless-stopped \
  --log-opt max-size=10m --log-opt max-file=3 \
  --memory "$ACTIVE_MEM" --memory-swap "$ACTIVE_MEM" --pids-limit 256 \
  --network "$NETWORK" --env-file "$RUNTIME_ENV" \
  -e PORT=8000 -e NOVA_DATA_DIR=/app/data -e NOVA_CANDIDATE_MODE=0 \
  -v "$APP_DIR/data:/app/data" -p "${HOST_PORT}:8000" \
  --entrypoint /bin/sh "$IMAGE" -c 'exec python -m uvicorn app.main:app --host 0.0.0.0 --port "${PORT:-8000}"' >/dev/null

say "7/9 Active liveness + root + memory soak"
LIVE_OK=0
for i in $(seq 1 100); do
  J="$(curl -fsS --connect-timeout 1 --max-time 2 "http://127.0.0.1:${HOST_PORT}/api/livez" 2>/dev/null || true)"
  if [[ -n "$J" ]] && printf '%s' "$J" | python3 -c 'import sys,json;j=json.load(sys.stdin);raise SystemExit(0 if j.get("ok") and j.get("version")=="NOVA-2.5.2" and j.get("candidate_mode") is False else 1)' 2>/dev/null; then LIVE_OK=1;break;fi
  sleep .25
done
[[ $LIVE_OK -eq 1 ]] || { sudo docker logs --tail 300 "$CONTAINER" || true; fail "final active livez 실패"; }
for i in $(seq 1 45); do
  curl -fsS -o /dev/null --connect-timeout 1 --max-time 2 "http://127.0.0.1:${HOST_PORT}/api/livez" || fail "final active livez fail $i"
  curl -fsS -o /dev/null --connect-timeout 1 --max-time 2 "http://127.0.0.1:${HOST_PORT}/" || fail "final active root fail $i"
  sleep 1
done
ACTIVE_SWAP_KB="$(sudo docker exec "$CONTAINER" sh -c "awk '/VmSwap:/{print \$2}' /proc/1/status" 2>/dev/null || echo 0)"
[[ "${ACTIVE_SWAP_KB:-0}" -eq 0 ]] || fail "새 active가 swap 사용: ${ACTIVE_SWAP_KB}KB"
RH="$(curl -fsS --connect-timeout 1 --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/realtime-health")"
printf '%s' "$RH" | python3 -c 'import sys,json;j=json.load(sys.stdin);assert j.get("ok") is True,j;assert int((j.get("lane") or {}).get("critical_overflow_events") or 0)==0,j;assert int((j.get("lane") or {}).get("handler_errors") or 0)==0,j;print("FINAL_RT_HEALTH=PASS")'
MEMJSON="$(curl -fsS --connect-timeout 1 --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/health")"
printf '%s' "$MEMJSON" | python3 -c 'import sys,json;j=json.load(sys.stdin);pg=j.get("performance_guard") or {};pm=pg.get("process_memory") or {};print("PROCESS_MEMORY_RSS_MB=",pm.get("rss_mb"),"SWAP_MB=",pm.get("swap_mb"),"GUARD=",pg.get("memory_guard"))'

say "8/9 Public UI atomic sync"
if [[ -d "$GUARD_STATIC" ]]; then
  for f in index.html nova.js nova.css sw.js manifest.webmanifest icon-192.png icon-512.png; do
    [[ -f "$ROOT/static/$f" ]] || continue
    sudo cp "$ROOT/static/$f" "$GUARD_STATIC/.$f.r6.tmp"
    sudo chmod 644 "$GUARD_STATIC/.$f.r6.tmp"
    sudo mv "$GUARD_STATIC/.$f.r6.tmp" "$GUARD_STATIC/$f"
  done
  sudo rm -f "$GUARD_CACHE"/* >/dev/null 2>&1 || true
  GUARD_SYNCED=1
fi
curl -fsS -o /dev/null --connect-timeout 1 --max-time 3 "http://127.0.0.1:${HOST_PORT}/api/livez" || fail "UI sync 후 livez 실패"

say "9/9 Deployment seal"
cat > "$DEPLOY_DIR/DEPLOYMENT_OK.txt" <<EOSEAL
status=PASS
version=NOVA-2.5.2
rev=2.5.2-ROOT-MEMORY-LIVENESS-R6
zip_sha256=$EXPECTED_ZIP_SHA256
image=$IMAGE
base_image=$BASE_IMAGE_ID
production_data_candidate=PASS
memory_guard=RAW_TICK_330S_STREAMING_JSONL_STAGGERED_STARTUP
candidate_swap_kb=$CAND_SWAP_KB
active_swap_kb=$ACTIVE_SWAP_KB
active_memory_limit=$ACTIVE_MEM
rollback_backup=$BACKUP
completed_at=$(date -Is)
EOSEAL
SUCCESS=1
echo "=== NOVA 2.5.2 ROOT MEMORY LIVENESS R6 DEPLOY PASS ==="
echo "BACKUP_PRESERVED=$BACKUP"
echo "ACTIVE_MEMORY=$(sudo docker stats --no-stream --format '{{.MemUsage}}' "$CONTAINER")"
